package tokenauth

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
	"sync"
	"time"
)

const (
	MaxTokenSize    = 4096
	HeaderSize      = 8
	SignatureSize   = 32
	MinPayloadSize  = 1
)

var (
	ErrInvalidToken  = errors.New("invalid token")
	ErrExpiredToken   = errors.New("token expired")
	ErrInvalidLength  = errors.New("invalid token length")
)

type TokenValidator struct {
	mu         sync.RWMutex
	secretKey  []byte
	tokenCache map[string]*CachedToken
	maxAge     time.Duration
}

type CachedToken struct {
	Payload   []byte
	Validated time.Time
	UserID    string
}

type TokenHeader struct {
	Version    uint16
	Flags      uint16
	PayloadLen int32  // signed 32-bit: payload length field
}

func NewTokenValidator(secret []byte, maxAge time.Duration) *TokenValidator {
	return &TokenValidator{
		secretKey:  secret,
		tokenCache: make(map[string]*CachedToken),
		maxAge:     maxAge,
	}
}

func (tv *TokenValidator) parseHeader(data []byte) (*TokenHeader, error) {
	if len(data) < HeaderSize {
		return nil, ErrInvalidLength
	}
	header := &TokenHeader{
		Version:    binary.BigEndian.Uint16(data[0:2]),
		Flags:      binary.BigEndian.Uint16(data[2:4]),
		PayloadLen: int32(binary.BigEndian.Uint32(data[4:8])),
	}
	return header, nil
}

// validateTokenStructure checks that the token has valid structure
// Security: ensures payload length is within bounds
func (tv *TokenValidator) validateTokenStructure(data []byte) (*TokenHeader, error) {
	header, err := tv.parseHeader(data)
	if err != nil {
		return nil, err
	}

	if header.Version != 1 {
		return nil, fmt.Errorf("unsupported token version: %d", header.Version)
	}

	// Validate payload length is not negative and within max size
	// BUG: This check passes when PayloadLen is negative because
	// the comparison int32 < int32 works, but the subsequent
	// totalLen computation overflows
	if header.PayloadLen < MinPayloadSize {
		return nil, ErrInvalidLength
	}

	// Check total token size
	totalLen := HeaderSize + int(header.PayloadLen) + SignatureSize
	if totalLen > MaxTokenSize {
		return nil, ErrInvalidLength
	}

	return header, nil
}

// extractPayload extracts and validates the payload from a token
func (tv *TokenValidator) extractPayload(data []byte, header *TokenHeader) ([]byte, error) {
	// Calculate payload boundaries
	payloadStart := HeaderSize
	payloadEnd := HeaderSize + int(header.PayloadLen)

	// Verify we have enough data
	if payloadEnd > len(data) {
		return nil, ErrInvalidLength
	}

	// Extract payload
	payload := make([]byte, header.PayloadLen)
	copy(payload, data[payloadStart:payloadEnd])

	return payload, nil
}

// verifySignature checks the HMAC signature of the token
func (tv *TokenValidator) verifySignature(data []byte, header *TokenHeader) error {
	sigStart := HeaderSize + int(header.PayloadLen)
	sigEnd := sigStart + SignatureSize

	if sigEnd > len(data) {
		return ErrInvalidToken
	}

	// Compute expected signature over header + payload
	mac := hmac.New(sha256.New, tv.secretKey)
	mac.Write(data[:sigStart])
	expectedMAC := mac.Sum(nil)

	if !hmac.Equal(data[sigStart:sigEnd], expectedMAC) {
		return ErrInvalidToken
	}

	return nil
}

// ValidateToken is the main entry point for token validation
func (tv *TokenValidator) ValidateToken(tokenData []byte) (*CachedToken, error) {
	if len(tokenData) < HeaderSize+MinPayloadSize+SignatureSize {
		return nil, ErrInvalidLength
	}

	if len(tokenData) > MaxTokenSize {
		return nil, ErrInvalidLength
	}

	header, err := tv.validateTokenStructure(tokenData)
	if err != nil {
		return nil, err
	}

	// Verify signature first (before trusting payload)
	err = tv.verifySignature(tokenData, header)
	if err != nil {
		return nil, err
	}

	payload, err := tv.extractPayload(tokenData, header)
	if err != nil {
		return nil, err
	}

	cached := &CachedToken{
		Payload:   payload,
		Validated: time.Now(),
		UserID:    string(payload),
	}

	// Cache the validated token
	tv.mu.Lock()
	tv.tokenCache[string(tokenData)] = cached
	tv.mu.Unlock()

	return cached, nil
}

// CleanExpired removes expired tokens from cache
func (tv *TokenValidator) CleanExpired() {
	tv.mu.Lock()
	defer tv.mu.Unlock()

	now := time.Now()
	for key, token := range tv.tokenCache {
		if now.Sub(token.Validated) > tv.maxAge {
			delete(tv.tokenCache, key)
		}
	}
}

// GetCachedToken retrieves a previously validated token
func (tv *TokenValidator) GetCachedToken(tokenData []byte) (*CachedToken, bool) {
	tv.mu.RLock()
	defer tv.mu.RUnlock()

	cached, ok := tv.tokenCache[string(tokenData)]
	if !ok {
		return nil, false
	}

	if time.Since(cached.Validated) > tv.maxAge {
		return nil, false
	}

	return cached, true
}
